",302002,60,"fuji_0"},h)g[403803]=b({e[9057],403803,13,107,219,"「福寿双全館の他にこんなええお湯があるとは……。こんな上等にもてなしてくれるやなんて、あんさんはほんまにええ子やなぁ。ならウチもお返しを用意せんと……せやな、今年の福寿双全館での場代、2割くらいまけたろか？」",200038,2,"deco/character/fuji_WQ","fuji_wq"},h)g[403804]=b({e[9057],403804,4,108,220,"「なになに？　どうやって空に箱飛ばしとるんかって？　そらもちろん、神様の力や……って、まさか信じた訳やあらへんよね？　中身が空やからに決まっとるやないの。も～、あんさんの分にはちゃんと入っとるから安心しぃ。」",200038,2,"deco/character/fuji_SD","fuji_sd"},h)g[403805]=b({e[17045],403805,2,18,221,"「あんさんがウチのこと、どうしても～ゆうて一生懸命誘ってくれたんやろ？　なに日差しでバテとんねん！　ほら、はよウチと一緒に水に入ったらどうや？」",200038,2,"deco/character/fuji_YZ",false,false,false,false,false,false,false,"1",1,4633,5000,2197,5358,14666,7333,7333,12166,12000,8000,7333,"fuji_xr"},h)g[403806]=b({e[17057],403806,999,29,222,false,200038,3,"deco/character/fuji_SLO",false,false,false,false,1,false,false,"1","fuji_slo"},h)g[403807]=b({e[17045],403807,6,109,223,"「新年おめでとさん！\nちょうど今、金魚を何匹か描いたところや。\n墨の滲み具合も上出来……あとは仕上げの『点睛』を残すのみやで。\n目を描いてあげたら、この子らはただの絵やのうなって、ほんまに泳げるようになる。\nほんで、福を携えて、すいーっと人の心ん中に入っていけるようになるんや。\nウチが新春で一番大事にしとるこの『福の儀』、あんさんと一緒に仕上げたい思て待っとったんやで。」",200038,2,"deco/character/fuji_cj",false,false,1,false,false,false,false,"1",1,4117,5000,2140,4150,5333,8433,7333,8133,11967,8133,3000,"fuji_cj"},h)g[403901]=b({e[46057],403901,false,110,224,false,200039,false,"deco/character/qixi",302002,60,1,false,false,false,171,"1",false,false,false,false,false,false,false,"30,-160,1.1","0,60,1","60,30,1",false,false,false,"0,80,1","40,80,1",false,false,false,1778,989,409,1437,828,1312,1958,1437,828,1312,1126,"qixi"},h)g[403902]=b({e[13034],403902,1,4,225,"「毎日毎日、ババアのお使いばっかだし、たまにはこうしてサボらねーとな。\nどうだ、オレ様の赤い糸、綺麗だろ？\nふふん、一本だけなら分けてやってもいいぜ？」",200039,1,"deco/character/qixi_0",302002,60,1,1,1767,973,423,1110,493,2229,2504,1110,684,2229,1261,false,false,false,false,false,false,false,false,false,false,false,false,"qixi_0"},h)g[403903]=b({e[21034],403903,2,39,226,"「チェ、見る目ねぇなぁ……。この砂の城、オレ様が何時間かけて作ったと思ってんだ？　そこらのヤツとは違ぇんだよ。んなことより、いたずらで壊されたら困るからちゃんと警戒しねぇとな！　お前も暇なら手伝ってくれ。」",200039,2,"deco/character/qixi_YZ",false,false,fals